from PIL import Image
im=Image.open('chess_board.png').convert('RGB')
w,h=im.size
s=w//8
for r in range(8):
    out=[]
    for c in range(8):
        x0=s*c+s//2-24; y0=s*r+s//2-24
        b=wh=0
        for yy in range(y0,y0+48,4):
            for xx in range(x0,x0+48,4):
                p=im.getpixel((xx,yy))
                v=(p[0]+p[1]+p[2])//3
                if v<60: b+=1
                if v>200: wh+=1
        if b>40: out.append('B')
        elif wh>40: out.append('W')
        else: out.append('.')
    print(''.join(out))
